  /* ---------------------------------------------------------------- 3. traçage */
  traceIntro: "La case d'essai de l'appli (`agents/trials.py` : Aiko et Ren sur le toit du lycée, série shōnen en noir et blanc à trames) passée par le **vrai code** du moteur, sans LLM. Seules une note de bible et une note de savoir-faire sont ajoutées à la main (marquées comme telles) pour montrer ces deux sources. Clique un morceau : la page remonte à son auteur.",
  removedNote: "Retiré par `sent_prompt` au moment de l'envoi : mot de couleur d'une série en noir et blanc (`monochrome_forbidden_terms`) ou mot du ton que contredit l'ambiance (`mood_conflicts`). Le prompt stocké sur la case le garde.",
  traceTabs: [
    { id: "stored", label: "Prompt de la case (fragments)", intro: "Ce que `build_prompt` stocke sur la case quand le rédacteur est désactivé ou en échec. Chaque morceau est surligné selon sa source.",
      notes: ["Description, action, lieu, mise en scène et ambiance partent **en français** : seuls plan et angle sont traduits.", "Le plan est un gros plan (« the face fills the frame ») mais l'action parle de « la jambe avant » : aucun filtre ici, contrairement au rédacteur.", "Le ton « lumineux » de la série ajoute « bright joyful atmosphere, warm light » à un duel au crépuscule."] },
    { id: "sent", label: "Envoyé à ComfyUI", intro: "Le même prompt tel qu'il part au flux avec références (`qwen-image-edit-ref-qualite`) : rôles `<imageN>` devant, tri et « identité seulement » derrière, anti-doublon, tonalité. Les mots barrés sont retirés au moment de l'envoi.",
      notes: ["« orangé », « rouge », « red » sont retirés (série en noir et blanc) : « contre-jour orangé » devient « contre-jour ».", "Ces phrases `<imageN>` sont la syntaxe de Qwen-Image Edit ; elles partent aussi vers FLUX 3 Klein."] },
    { id: "negative", label: "Prompt négatif", intro: "Le négatif du flux, complété par le code. Rappel : il n'est lu qu'à vrai CFG (cfg > 1, palier Qualité)." },
    { id: "flux", label: "Grille FLUX 3 Klein", intro: "Le même prompt passé par `cite_boxes` comme pour le preset `flux3-klein-edit-ref-qualite-layout` : boîtes lues dans la mise en scène, `<obj_N>` après la première mention de chaque nom.",
      notes: ["Avec des références, la première mention de « Aiko » est dans la phrase de rôle `<image1>` : c'est là que `<obj_1>` atterrit, pas dans la description de la scène."] },
    { id: "writer", label: "Ce que reçoit le rédacteur", intro: "Le message utilisateur réellement rendu par `redacteur-image.yaml` pour la même case (bloc `<contexte>` JSON coupé ici). Le LLM part de là pour écrire son paragraphe anglais.",
      notes: ["Les placeholders « (none) », « (ordinary panel…) » sont écrits dans le code (`template_values`).", "Les traits des personnages arrivent en français (fiches) mêlés aux mots-clés anglais."] },
  ],
